.overlay {
  position: fixed;
  inset: 0;
  z-index: 5000;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  overflow: hidden;
}

// Étape 1 : flou seul, sans aucune teinte — une simple loupe sur ce qu'il y a derrière.
.blurLayer {
  position: absolute;
  inset: 0;
  -webkit-backdrop-filter: blur(0px);
}

// Étape 2 : grille de grosses tuiles peintes une à une (cf. TSX) plutôt qu'un voile continu.
.tileGrid {
  position: absolute;
  inset: 0;
}

.tile {
  position: absolute;
  // Léger débord pour recouvrir la jointure avec les tuiles voisines (anti-aliasing/arrondis).
  margin: -1px;
  background:
    radial-gradient(140% 160% at 100% 0%, rgba(60, 210, 255, 0.9), rgba(0, 60, 130, 0.97) 55%, rgba(0, 20, 55, 1) 100%);
  // Chaque tuile lit le dégradé à sa propre position dans le viewport (pas re-scalé par tuile),
  // pour que l'ensemble reforme un dégradé continu une fois toutes les tuiles posées.
  background-attachment: fixed;
  background-size: 100vw 100vh;
  background-position: 0 0;
}

.textBlock {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  text-align: center;
}

.brand {
  font-family: 'Ethnocentric', 'Orbitron', sans-serif;
  font-weight: 400;
  font-size: clamp(64px, 11vw, 160px);
  line-height: 1;
  letter-spacing: 0.05em;
  color: #eafcff;
  text-shadow: 0 0 16px rgba(255, 255, 255, 0.6), 0 0 40px rgba(0, 240, 255, 0.5);
}

// Petit, tout en majuscules et très espacé — le style "M O D É L I S A T I O N".
