1	import React, { useState, useRef, useEffect } from 'react';
2	import { motion, Variants } from 'framer-motion';
3	import clsx from 'clsx';
4	import {
5	  FileSliders,
6	  Box,
7	  MousePointer2,
8	  Move3d,
9	  RotateCw,
10	  Maximize,
11	  Upload,
12	  Code,
13	  Maximize2,
14	  Eye,
15	  Palette,
16	  Layers
17	} from 'lucide-react';
18	import styles from './Sidebar.module.scss';
19	import { CustomTooltip } from './CustomTooltip';
20	
21	interface SidebarProps {
22	  activeTab: '3d-view' | 'settings' | 'developer';
23	  onTabChange: (tab: 'box' | 'settings' | 'developer') => void;
24	  onOpenModel?: () => void;
25	}
26	
27	export const Sidebar: React.FC<SidebarProps> = ({
28	  activeTab,
29	  onTabChange,
30	  onOpenModel
31	}) => {
32	  const [activeTool, setActiveTool] = useState<'select' | 'move' | 'rotate' | 'scale' | 'texture' | 'layers'>('select');
33	  const [isPreviewActive, setIsPreviewActive] = useState(false);
34	  const [naturalWidth, setNaturalWidth] = useState<number | null>(null);
35	  const bottomToolbarRef = useRef<HTMLDivElement>(null);
36	  const fileInputRef = useRef<HTMLInputElement>(null);
37	
38	  const topToolbarRef = useRef<HTMLDivElement>(null);
39	  const buttonRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
40	  const [indicatorStyle, setIndicatorStyle] = React.useState<React.CSSProperties>({});
41	
42	  /** L'onglet « Modélisation » porte la valeur 'settings'. */
43	  const isModeling = activeTab === 'settings';
44	
45	  const handleUploadClick = () => {
46	    fileInputRef.current?.click();
47	  };
48	
49	  const SPACE_LABELS: Record<'box' | 'settings' | 'developer' | 'layers', string> = {
50	    box: 'Préparation',
51	    settings: 'Modélisation',
52	    developer: 'Dev',
53	    layers: 'Prévisualisation',
54	  };
55	
56	  /**
57	   * Joue le rideau "APEX / <espace>" (voir SpaceTransitionOverlay) puis exécute `onCovered`
58	   * une fois l'écran masqué — c'est là, et pas avant, que le vrai changement d'onglet doit
59	   * avoir lieu pour ne jamais être visible pendant la transition.
60	   */
61	  const playSpaceTransition = (label: string, onCovered: () => void) => {
62	    window.dispatchEvent(new CustomEvent('apex-space-transition', { detail: { label, onCovered } }));
63	  };
64	
65	  const handleTopTabClick = (tabName: 'box' | 'settings' | 'developer') => {
66	    playSpaceTransition(SPACE_LABELS[tabName], () => {
67	      setActiveTool('select');
68	      onTabChange(tabName);
69	      setIsPreviewActive(false);
70	      window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
71	    });
72	  };
73	
74	  const handleToolClick = (tool: 'select' | 'move' | 'rotate' | 'scale' | 'texture') => {
75	    const newTool = activeTool === tool ? 'select' : tool;
76	    setActiveTool(newTool);
77	    window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
78	  };
79	
80	  const handleLayerClick = () => {
81	    const entering = activeTool !== 'layers';
82	
83	    if (entering) {
84	      // L'ancien fondu séquencé des panneaux (avant le rideau plein écran) n'a plus de raison
85	      // d'être : le rideau masque déjà tout pendant que ce switch se produit, donc tout bascule
86	      // d'un coup sous le voile plutôt qu'en deux temps visibles.
87	      playSpaceTransition(SPACE_LABELS.layers, () => {
88	        setActiveTool('layers');
89	        if (bottomToolbarRef.current) {
90	          setNaturalWidth(bottomToolbarRef.current.getBoundingClientRect().width);
91	        }
92	        setIsPreviewActive(true);
93	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'layers' } }));
94	        window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: true } }));
95	      });
96	    } else {
97	      playSpaceTransition(SPACE_LABELS.box, () => {
98	        setActiveTool('select');
99	        setIsPreviewActive(false);
100	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
101	        window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
102	      });
103	    }
104	  };
105	
106	  useEffect(() => {
107	    const handleKeyDown = (e: KeyboardEvent) => {
108	      if (['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement)?.tagName)) {
109	        return;
110	      }
111	
112	      const key = e.key.toLowerCase();
113	      if (key === 'm') {
114	        const newTool = activeTool === 'move' ? 'select' : 'move';
115	        setActiveTool(newTool);
116	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
117	      } else if (key === 'r') {
118	        const newTool = activeTool === 'rotate' ? 'select' : 'rotate';
119	        setActiveTool(newTool);
120	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
121	      } else if (key === 's') {
122	        const newTool = activeTool === 'scale' ? 'select' : 'scale';
123	        setActiveTool(newTool);
124	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
125	      } else if (key === 't') {
126	        const newTool = activeTool === 'texture' ? 'select' : 'texture';
127	        setActiveTool(newTool);
128	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
129	      } else if (key === 'escape') {
130	        setActiveTool('select');
131	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
132	      }
133	    };
134	
135	    window.addEventListener('keydown', handleKeyDown);
136	    return () => {
137	      window.removeEventListener('keydown', handleKeyDown);
138	    };
139	  }, [activeTool]);
140	
141	  useEffect(() => {
142	    if (topToolbarRef.current && buttonRefs.current.size > 0) {
143	      const activeButtonKey = activeTool === 'layers' ? 'layers' : (activeTab === '3d-view' ? 'box' : activeTab);
144	      const activeButton = buttonRefs.current.get(activeButtonKey);
145	
146	      if (activeButton) {
147	        const toolbarRect = topToolbarRef.current.getBoundingClientRect();
148	        const buttonRect = activeButton.getBoundingClientRect();
149	
150	        setIndicatorStyle({
151	          width: buttonRect.width,
152	          height: buttonRect.height,
153	          left: buttonRect.left - toolbarRect.left,
154	          top: buttonRect.top - toolbarRect.top,
155	          opacity: 1,
156	        });
157	      } else {
158	        setIndicatorStyle((prev) => ({ ...prev, opacity: 0 }));
159	      }
160	    }
161	  }, [activeTab, activeTool]);
162	
163	  const iconVariants: Variants = {
164	    visible: (i: number) => ({
165	      opacity: 1,
166	      y: 0,
167	      scale: 1,
168	      transition: {
169	        delay: i * 0.04,
170	        duration: 0.3,
171	        ease: [0.16, 1, 0.3, 1] as const
172	      }
173	    }),
174	    hidden: (i: number) => ({
175	      opacity: 0,
176	      y: 15,
177	      scale: 0.95,
178	      transition: {
179	        delay: i * 0.04,
180	        duration: 0.25,
181	        ease: [0.25, 1, 0.5, 1] as const
182	      }
183	    })
184	  };
185	
186	  return (
187	    <div className={styles.container} data-apex-chrome-panel>
188	      {/* Top Toolbar (Navigation & Main Views) */}
189	      <div
190	        ref={topToolbarRef}
191	        className={clsx(styles.toolbar, styles.topToolbar)}
192	      >
193	        <div className={styles.activeIndicator} style={indicatorStyle}></div>
194	
195	        <CustomTooltip content="Apex Slicer Studio" description="Logiciel de préparation et de découpe 3D haute performance pour l'impression additive professionnelle.">
196	          <div className={styles.logoContainer}>
197	            <img src="/logo.svg" alt="Logo" className={styles.logoImg} />
198	          </div>
199	        </CustomTooltip>
200	
201	        <div className={styles.topSeparator} />
202	
203	        <CustomTooltip content="Vue 3D Perspective" description="Basculez sur l'espace de travail principal pour inspecter et manipuler vos modèles sur le plateau d'impression.">
204	          <button
205	            ref={(el) => { if (el) buttonRefs.current.set('box', el); }}
206	            className={clsx(styles.button, styles.topButton, {
207	              [styles.active]: activeTab === '3d-view' && !isPreviewActive,
208	            })}
209	            onClick={() => handleTopTabClick('box')}
210	          >
211	            <FileSliders size={22} />
212	            <span className={styles.topButtonLabel}>Préparation</span>
213	          </button>
214	        </CustomTooltip>
215	
216	        <CustomTooltip content="Prévisualisation" description="Visualisez le parcours de la buse et ajustez différents paramètres si cela ne vous convient pas.">
217	          <button
218	            ref={(el) => { if (el) buttonRefs.current.set('layers', el); }}
219	            className={clsx(styles.button, styles.topButton, {
220	              [styles.active]: isPreviewActive,
221	            })}
222	            onClick={handleLayerClick}
223	          >
224	            <Layers size={22} />
225	            <span className={styles.topButtonLabel}>Prévisualisation</span>
226	          </button>
227	        </CustomTooltip>
228	
229	        <CustomTooltip content="Modélisation" description="Accédez aux outils de modélisation et de préparation de votre modèle.">
230	          <button
231	            ref={(el) => { if (el) buttonRefs.current.set('settings', el); }}
232	            className={clsx(styles.button, styles.topButton, {
233	              [styles.active]: activeTab === 'settings',
234	            })}
235	            onClick={() => handleTopTabClick('settings')}
236	          >
237	            <Box size={22} />
238	            <span className={styles.topButtonLabel}>Modélisation</span>
239	          </button>
240	        </CustomTooltip>
241	
242	        <CustomTooltip content="Console Développeur" description="Inspectez les flux G-code générés en temps réel et les journaux de diagnostic système.">
243	          <button
244	            ref={(el) => { if (el) buttonRefs.current.set('developer', el); }}
245	            className={clsx(styles.button, styles.topButton, {
246	              [styles.active]: activeTab === 'developer',
247	            })}
248	            onClick={() => handleTopTabClick('developer')}
249	          >
250	            <Code size={22} />
251	            <span className={styles.topButtonLabel}>Dev</span>
252	          </button>
253	        </CustomTooltip>
254	      </div>
255	
256	      {/* Bottom Toolbar (Action, Manipulation 3D) */}
257	      <motion.div
258	        ref={bottomToolbarRef}
259	        className={clsx(styles.toolbar, styles.bottomToolbar)}
260	        initial={false}
261	        animate={isModeling ? {
262	          // Mode modélisation : la barre slicer se rétracte sur elle-même pour céder sa
263	          // place à la barre d'opérations CAD, qui vient occuper le même emplacement.
264	          // On ne peut pas compter sur un clip : `.bottomToolbar` force `overflow: visible`,
265	          // donc c'est l'opacité qui escamote réellement les icônes.
266	          x: 0,
267	          opacity: 0,
268	          width: 0,
269	          height: 0,
270	          paddingTop: 0,
271	          paddingBottom: 0,
272	          marginTop: -10, // absorbe le `gap: 10px` de la pile pour ne pas laisser de trou
273	          borderRadius: 22
274	        } : isPreviewActive && naturalWidth !== null ? {
275	          x: [0, 0, 480],
276	          width: [naturalWidth, naturalWidth, 56],
277	          height: [44, 44, 340],
278	          borderRadius: [22, 22, 20],
279	          opacity: 1,
280	          marginTop: 0
281	        } : {
282	          x: 0,
283	          width: "auto",
284	          height: 44,
285	          borderRadius: 22,
286	          opacity: 1,
287	          marginTop: 0
288	        }}
289	        transition={isModeling ? {
290	          duration: 0.45,
291	          ease: [0.4, 0, 0.2, 1]
292	        } : {
293	          duration: 1.1,
294	          times: [0, 0.45, 1],
295	          ease: [0.25, 1, 0.5, 1]
296	        }}
297	        style={{ originX: 0.5, originY: 0.5, pointerEvents: isModeling ? 'none' : 'auto' }}
298	      >
299	        <motion.div custom={0} variants={iconVariants} animate={isPreviewActive ? "hidden" : "visible"} initial="visible" className="flex items-center">
300	          <CustomTooltip content="Outil de Sélection" description="Cliquez sur n'importe quel modèle 3D sur le plateau pour le sélectionner et afficher ses propriétés.">
301	            <button
302	              className={clsx(styles.button, styles.bottomButton, {
303	                [styles.active]: activeTool === 'select',
304	              })}
305	              onClick={() => handleToolClick('select')}
306	            >
307	              <MousePointer2 size={16} />
308	            </button>
309	          </CustomTooltip>
310	        </motion.div>
311	
312	        <motion.div custom={1} variants={iconVariants} animate={isPreviewActive ? "hidden" : "visible"} initial="visible" className="flex items-center">
313	          <CustomTooltip content="Outil de Déplacement (Move - M)" description="Affichez les gizmos directionnels pour repositionner précisément l'objet sur le plateau d'impression. (Raccourci : M)">
314	            <button
315	              className={clsx(styles.button, styles.bottomButton, {
316	                [styles.active]: activeTool === 'move',
317	              })}
318	              onClick={() => handleToolClick('move')}
319	            >
320	              <Move3d size={16} />
321	            </button>
322	          </CustomTooltip>
323	        </motion.div>
324	
325	        <motion.div custom={2} variants={iconVariants} animate={isPreviewActive ? "hidden" : "visible"} initial="visible" className="flex items-center">
326	          <CustomTooltip content="Outil de Rotation (Rotate - R)" description="Faites pivoter le modèle selon les axes X, Y et Z pour optimiser son orientation de contact. (Raccourci : R)">
327	            <button
328	              className={clsx(styles.button, styles.bottomButton, {
329	                [styles.active]: activeTool === 'rotate',
330	              })}
331	              onClick={() => handleToolClick('rotate')}
332	            >
333	              <RotateCw size={16} />
334	            </button>
335	          </CustomTooltip>
336	        </motion.div>
337	
338	        <motion.div custom={3} variants={iconVariants} animate={isPreviewActive ? "hidden" : "visible"} initial="visible" className="flex items-center">
339	          <CustomTooltip content="Outil de Mise à l'échelle (Scale - S)" description="Modifiez la taille et les proportions du modèle 3D sur le plateau d'impression. (Raccourci : S)">
340	            <button
341	              className={clsx(styles.button, styles.bottomButton, {
