90	  const [selectedModel, setSelectedModel] = useState<string | null>(null);
91	  const [selectedFeatureId, setSelectedFeatureId] = useState<string | null>(null);
92	  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
93	  const [activeTool, setActiveTool] = useState<FeatureKind | null>(null);
