655	      <AnimatePresence initial={false}>
656	        {activeTool === 'sketch' && (
657	          <motion.div
658	            className={styles.sketchBar}
659	            data-apex-chrome-panel
660	            initial={{ opacity: 0, y: -8 }}
661	            animate={{ opacity: 1, y: 0 }}
662	            exit={{ opacity: 0, y: -8 }}
663	            transition={{ duration: 0.22, ease: [0.4, 0, 0.2, 1] }}
664	          >
665	            <div className={styles.sketchBarInner}>
666	              {SKETCH_ENTITIES.map(({ kind, icon: Icon }) => (
667	                <CustomTooltip
668	                  key={kind}
669	                  content={SKETCH_ENTITY_LABELS[kind]}
670	                  description="Sommets connectables aux autres formes de l'esquisse."
671	                >
672	                  <button
673	                    className={clsx(styles.barButton, { [styles.active]: sketchEntity === kind })}
674	                    onClick={() => handleSketchEntity(kind)}
675	                    aria-label={SKETCH_ENTITY_LABELS[kind]}
676	                  >
677	                    <Icon className="w-5 h-5" />
678	                  </button>
679	                </CustomTooltip>
680	              ))}
681	            </div>
682	          </motion.div>
683	        )}
