.bottomToolbar {
  padding: 6px 10px;
  border-radius: 22px;
  gap: 6px;
  overflow: visible !important;
}

// Slot du mode modélisation : occupe tout le conteneur commun une fois déformé, et
// dispose les boutons CAD injectés par portail (voir Sidebar.tsx / ModelingSidebar.tsx)
// exactement comme l'ancien `.opsBarInner`.
.modelingSlot {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 6px;
}

.button {
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  color: rgba(255, 255, 255, 0.85);
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;
  position: relative;
  z-index: 2;

  &:hover:not(:disabled) {
    color: rgba(255, 255, 255, 1);
    background: rgba(255, 255, 255, 0.18);
  }

  &:disabled {
    opacity: 0.3;
    cursor: not-allowed;
  }
}

.topButton {
  height: 42px;
  padding: 0 14px;
  border-radius: 14px;
  gap: 8px;

  &.active {
    color: #00f0ff;
  }
}

.topButtonLabel {
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}

.sliceButton {
  background: rgba(0, 240, 255, 0.15);
  color: #00f0ff;
  border: none;

  &:hover {
    background: rgba(0, 240, 255, 0.25) !important;
  }
}

.configButton {
  color: #a78bfa;
  &:hover {
    background: rgba(167, 139, 250, 0.15) !important;
  }
}

.logoContainer {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  padding: 2px;

  .logoImg {
    width: 32px;
    height: 32px;
    object-fit: contain;
    filter: brightness(0) invert(1);
  }
}

.bottomButton {
  width: 32px;
  height: 32px;
  border-radius: 10px;

  svg {
    width: 16px;
    height: 16px;
    transition: transform 0.2s ease;
  }

  &.active {
    background: rgba(0, 240, 255, 0.15);
    box-shadow:
      0 0 8px rgba(0, 240, 255, 0.2),
      inset 0 0 6px rgba(0, 240, 255, 0.1);
    color: #00f0ff;
  }
}

.activeIndicator {
  position: absolute;
  background: rgba(255, 255, 255, 0.12);
  box-shadow: 
    0 0 14px rgba(255, 255, 255, 0.15), 
    inset 0 0 10px rgba(255, 255, 255, 0.05);
  border-radius: 14px;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  pointer-events: none;
  z-index: 1;
  opacity: 0;
}

.uploadActionButton {
  color: #00f0ff !important;
  width: 32px;
  height: 32px;
  border-radius: 10px;

  &:hover {
    background: rgba(0, 240, 255, 0.15) !important;
  }
}

.separator {
  width: 1px;
  height: 18px;
  background: rgba(255, 255, 255, 0.2);
  margin: 0 4px;
}

.topSeparator {
  width: 1px;
  height: 24px;
  background: rgba(255, 255, 255, 0.2);
  margin: 0 2px;
}

