$accent: #00f0ff;
$panel-bg: rgba(10, 15, 26, 0.25);
$panel-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);

.container {
  position: fixed;
  top: 96px;
  left: 24px;
  bottom: 96px;
  width: 268px;
  z-index: 100;
  display: flex;
  flex-direction: column;
  pointer-events: none;
}

.panel {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: $panel-bg;
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border: none;
  border-radius: 18px;
  box-shadow: $panel-shadow;
  pointer-events: auto;
  overflow: hidden;
}

.header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 16px 10px;
  color: rgba(255, 255, 255, 0.9);
  font-family: 'Orbitron', sans-serif !important;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  flex-shrink: 0;
}

.headerIcon {
  color: $accent;
  filter: drop-shadow(0 0 6px rgba(0, 240, 255, 0.5));
}

.sectionLabel {
  padding: 10px 16px 6px;
  color: rgba(255, 255, 255, 0.4);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  flex-shrink: 0;
}

/* ---- Barre d'outils CAD ---- */

.toolGrid {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
  padding: 0 12px 8px;
  flex-shrink: 0;
}

.toolButton {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 10px 4px;
  background: transparent;
  border: none;
  border-radius: 10px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 9px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;

  &:hover:not(:disabled) {
    color: white;
    background: rgba(255, 255, 255, 0.08);
  }

  &.active {
    color: $accent;
    background: rgba(0, 240, 255, 0.14);
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.2);
  }

  &:disabled {
    opacity: 0.32;
    cursor: not-allowed;
  }
}

/* ---- Sélecteur de granularité de sélection ---- */

.segmented {
  position: relative;
  display: flex;
  margin: 0 12px 8px;
  padding: 4px;
  background: rgba(0, 0, 0, 0.25);
  border-radius: 12px;
  gap: 2px;
  flex-shrink: 0;
}

.activeIndicator {
  position: absolute;
  background: rgba(0, 240, 255, 0.18);
  box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  border-radius: 9px;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  pointer-events: none;
  z-index: 1;
  opacity: 0;
}

.segmentButton {
  position: relative;
  z-index: 2;
  flex: 1;
  padding: 6px 4px;
  background: transparent;
  border: none;
  border-radius: 9px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  cursor: pointer;
  transition: color 0.2s ease;
  outline: none;

  &:hover:not(:disabled) { color: white; }
  &.active { color: $accent; }

  &:disabled {
    opacity: 0.32;
    cursor: not-allowed;
  }
}

/* ---- Arborescence ---- */

.treeScroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0 8px 8px;

  &::-webkit-scrollbar { width: 4px; }
  &::-webkit-scrollbar-track { background: transparent; }
  &::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.15);
    border-radius: 2px;
  }
}

.treeList {
  list-style: none;
  margin: 0;
