// pour ne jamais élargir la barre principale — visible seulement quand l'outil Esquisse
// de `.opsBar` est actif.
.sketchBar {
  position: fixed;
  top: 144px;
  left: 0;
  right: 0;
  z-index: 1001;
  display: flex;
  justify-content: center;
  pointer-events: none;
}

