  border: none;
  border-radius: 12px;
  box-shadow: $panel-shadow;
  pointer-events: auto;
}

.barButton {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  background: transparent;
  border: none;
  border-radius: 10px;
  color: rgba(255, 255, 255, 0.65);
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;
  flex-shrink: 0;

  &:hover:not(:disabled) {
    color: white;
    background: rgba(255, 255, 255, 0.08);
  }

  &.active {
    color: $accent;
    background: rgba(0, 240, 255, 0.16);
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  }

  &:disabled {
    opacity: 0.32;
    cursor: not-allowed;
  }
}

