61	   * Joue le rideau "APEX / <espace>" (voir SpaceTransitionOverlay) puis exécute `onCovered`
62	   * une fois l'écran masqué — c'est là, et pas avant, que le vrai changement d'onglet doit
63	   * avoir lieu pour ne jamais être visible pendant la transition.
64	   */
65	  const playSpaceTransition = (label: string, onCovered: () => void) => {
66	    window.dispatchEvent(new CustomEvent('apex-space-transition', { detail: { label, onCovered } }));
67	  };
68	
69	  const handleTopTabClick = (tabName: 'box' | 'settings' | 'developer') => {
70	    playSpaceTransition(SPACE_LABELS[tabName], () => {
71	      setActiveTool('select');
72	      onTabChange(tabName);
73	      setIsPreviewActive(false);
74	      window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
75	    });
76	  };
77	
