40	  // séparateurs) ne change jamais, donc une mesure une fois montée suffit — c'est la valeur
41	  // cible numérique vers laquelle animer au retour au mode slicer (une keyframe `"auto"`
42	  // mélangée à des nombres dans le même tableau n'anime pas correctement avec framer-motion).
43	  const [boxWidth, setBoxWidth] = useState<number | null>(null);
44	  const bottomToolbarRef = useRef<HTMLDivElement>(null);
45	  const fileInputRef = useRef<HTMLInputElement>(null);
46	
47	  const topToolbarRef = useRef<HTMLDivElement>(null);
48	  // Slot où ModelingSidebar injecte ses boutons CAD via un portail (id stable plutôt qu'un
49	  // ref transmis en prop : les deux composants sont des siblings montés indépendamment dans
50	  // Index.tsx, un id DOM est la façon la plus simple de se retrouver).
51	  const modelingSlotRef = useRef<HTMLDivElement>(null);
52	  const buttonRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
53	  const [indicatorStyle, setIndicatorStyle] = React.useState<React.CSSProperties>({});
54	
55	  /** L'onglet « Modélisation » porte la valeur 'settings'. */
56	  const isModeling = activeTab === 'settings';
57	
58	  const handleUploadClick = () => {
59	    fileInputRef.current?.click();
60	  };
61	
62	  const SPACE_LABELS: Record<'box' | 'settings' | 'developer' | 'layers', string> = {
63	    box: 'Préparation',
64	    settings: 'Modélisation',
65	    developer: 'Dev',
66	    layers: 'Prévisualisation',
67	  };
68	
69	  /**
70	   * Joue le rideau "APEX / <espace>" (voir SpaceTransitionOverlay) puis exécute `onCovered`
71	   * une fois l'écran masqué — c'est là, et pas avant, que le vrai changement d'onglet doit
72	   * avoir lieu pour ne jamais être visible pendant la transition. Mesure aussi la forme
73	   * actuelle du conteneur d'outils juste avant : quel que soit le mode de départ (slicer,
74	   * prévisualisation ou modélisation), c'est de là que doit partir l'animation de
75	   * déformation vers le mode suivant — jamais une valeur figée valable pour un seul sens.
76	   */
77	  const playSpaceTransition = (label: string, onCovered: () => void) => {
78	    if (bottomToolbarRef.current) {
79	      const rect = bottomToolbarRef.current.getBoundingClientRect();
80	      setFromGeometry({ width: rect.width, height: rect.height });
81	    }
82	    window.dispatchEvent(new CustomEvent('apex-space-transition', { detail: { label, onCovered } }));
83	  };
