163	      setBoxWidth(bottomToolbarRef.current.getBoundingClientRect().width);
164	    }
165	  }, [boxWidth, isModeling, isPreviewActive]);
166	
167	  useEffect(() => {
168	    if (topToolbarRef.current && buttonRefs.current.size > 0) {
169	      const activeButtonKey = activeTool === 'layers' ? 'layers' : (activeTab === '3d-view' ? 'box' : activeTab);
170	      const activeButton = buttonRefs.current.get(activeButtonKey);
171	
172	      if (activeButton) {
