1	import React, { useState, useRef, useEffect } from 'react';
2	import { motion, Variants } from 'framer-motion';
3	import clsx from 'clsx';
4	import {
5	  FileSliders,
6	  Box,
7	  MousePointer2,
8	  Move3d,
9	  RotateCw,
10	  Maximize,
11	  Upload,
12	  Code,
13	  Maximize2,
14	  Eye,
15	  Palette,
16	  Layers
17	} from 'lucide-react';
18	import styles from './Sidebar.module.scss';
19	import { CustomTooltip } from './CustomTooltip';
20	
21	interface SidebarProps {
22	  activeTab: '3d-view' | 'settings' | 'developer';
23	  onTabChange: (tab: 'box' | 'settings' | 'developer') => void;
24	  onOpenModel?: () => void;
25	}
26	
27	export const Sidebar: React.FC<SidebarProps> = ({
28	  activeTab,
29	  onTabChange,
30	  onOpenModel
31	}) => {
32	  const [activeTool, setActiveTool] = useState<'select' | 'move' | 'rotate' | 'scale' | 'texture' | 'layers'>('select');
33	  const [isPreviewActive, setIsPreviewActive] = useState(false);
34	  // Géométrie du conteneur juste avant de lancer la transition en cours : mesurée à la volée
35	  // (voir `playSpaceTransition`) quel que soit le mode de départ (slicer, prévisualisation
36	  // ou modélisation), pour que l'animation de conteneur parte toujours de sa forme réelle et
37	  // non d'une valeur figée valable pour un seul sens de transition.
38	  const [fromGeometry, setFromGeometry] = useState<{ x: number; width: number; height: number; borderRadius: number } | null>(null);
39	  // Largeur naturelle de la barre slicer (mode "box") : son contenu (8 boutons + 2
40	  // séparateurs) ne change jamais, donc une mesure une fois montée suffit — c'est la valeur
41	  // cible numérique vers laquelle animer au retour au mode slicer (une keyframe `"auto"`
42	  // mélangée à des nombres dans le même tableau n'anime pas correctement avec framer-motion).
43	  const [boxWidth, setBoxWidth] = useState<number | null>(null);
44	  const bottomToolbarRef = useRef<HTMLDivElement>(null);
45	  const fileInputRef = useRef<HTMLInputElement>(null);
46	
47	  const topToolbarRef = useRef<HTMLDivElement>(null);
48	  // Slot où ModelingSidebar injecte ses boutons CAD via un portail (id stable plutôt qu'un
49	  // ref transmis en prop : les deux composants sont des siblings montés indépendamment dans
50	  // Index.tsx, un id DOM est la façon la plus simple de se retrouver).
51	  const modelingSlotRef = useRef<HTMLDivElement>(null);
52	  const buttonRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
53	  const [indicatorStyle, setIndicatorStyle] = React.useState<React.CSSProperties>({});
54	
55	  /** L'onglet « Modélisation » porte la valeur 'settings'. */
56	  const isModeling = activeTab === 'settings';
57	
58	  // Gabarit cible du conteneur commun pour chaque mode — voir le commentaire au-dessus de
59	  // `.bottomToolbar` dans le JSX pour la logique d'animation qui s'en sert.
60	  const targetGeometry = isModeling
61	    ? { x: 0, width: 260, height: 50, borderRadius: 14 } // barre CAD (6 boutons de 38px)
62	    : isPreviewActive
63	      ? { x: 480, width: 56, height: 340, borderRadius: 20 } // colonne de calques
64	      : { x: 0, width: boxWidth ?? 332, height: 44, borderRadius: 22 }; // barre slicer
65	
66	  const handleUploadClick = () => {
67	    fileInputRef.current?.click();
68	  };
69	
70	  const SPACE_LABELS: Record<'box' | 'settings' | 'developer' | 'layers', string> = {
71	    box: 'Préparation',
72	    settings: 'Modélisation',
73	    developer: 'Dev',
74	    layers: 'Prévisualisation',
75	  };
76	
77	  /**
78	   * Joue le rideau "APEX / <espace>" (voir SpaceTransitionOverlay) puis exécute `onCovered`
79	   * une fois l'écran masqué — c'est là, et pas avant, que le vrai changement d'onglet doit
80	   * avoir lieu pour ne jamais être visible pendant la transition. Mesure aussi la forme
81	   * actuelle du conteneur d'outils juste avant : quel que soit le mode de départ (slicer,
82	   * prévisualisation ou modélisation), c'est de là que doit partir l'animation de
83	   * déformation vers le mode suivant — jamais une valeur figée valable pour un seul sens.
84	   */
85	  const playSpaceTransition = (label: string, onCovered: () => void) => {
86	    if (bottomToolbarRef.current) {
87	      const rect = bottomToolbarRef.current.getBoundingClientRect();
88	      const computedRadius = parseFloat(getComputedStyle(bottomToolbarRef.current).borderTopLeftRadius) || 22;
89	      // `x` n'est pas lisible depuis le DOM (c'est un translateX posé par framer-motion, pas
90	      // une position absolue) : on reprend celui du mode qu'on est en train de quitter,
91	      // calculé par la même table que `targetGeometry` ci-dessous.
92	      setFromGeometry({ x: targetGeometry.x, width: rect.width, height: rect.height, borderRadius: computedRadius });
93	    }
94	    window.dispatchEvent(new CustomEvent('apex-space-transition', { detail: { label, onCovered } }));
95	  };
96	
97	  const handleTopTabClick = (tabName: 'box' | 'settings' | 'developer') => {
98	    playSpaceTransition(SPACE_LABELS[tabName], () => {
99	      setActiveTool('select');
100	      onTabChange(tabName);
101	      setIsPreviewActive(false);
102	      window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
103	    });
104	  };
105	
106	  const handleToolClick = (tool: 'select' | 'move' | 'rotate' | 'scale' | 'texture') => {
107	    const newTool = activeTool === tool ? 'select' : tool;
108	    setActiveTool(newTool);
109	    window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
110	  };
111	
112	  const handleLayerClick = () => {
113	    const entering = activeTool !== 'layers';
114	
115	    if (entering) {
116	      // L'ancien fondu séquencé des panneaux (avant le rideau plein écran) n'a plus de raison
117	      // d'être : le rideau masque déjà tout pendant que ce switch se produit, donc tout bascule
118	      // d'un coup sous le voile plutôt qu'en deux temps visibles.
119	      playSpaceTransition(SPACE_LABELS.layers, () => {
120	        setActiveTool('layers');
121	        setIsPreviewActive(true);
122	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'layers' } }));
123	        window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: true } }));
124	      });
125	    } else {
126	      playSpaceTransition(SPACE_LABELS.box, () => {
127	        setActiveTool('select');
128	        setIsPreviewActive(false);
129	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
130	        window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
131	      });
132	    }
133	  };
134	
135	  useEffect(() => {
136	    const handleKeyDown = (e: KeyboardEvent) => {
137	      if (['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement)?.tagName)) {
138	        return;
139	      }
140	
141	      const key = e.key.toLowerCase();
142	      if (key === 'm') {
143	        const newTool = activeTool === 'move' ? 'select' : 'move';
144	        setActiveTool(newTool);
145	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
146	      } else if (key === 'r') {
147	        const newTool = activeTool === 'rotate' ? 'select' : 'rotate';
148	        setActiveTool(newTool);
149	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
150	      } else if (key === 's') {
151	        const newTool = activeTool === 'scale' ? 'select' : 'scale';
152	        setActiveTool(newTool);
153	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
154	      } else if (key === 't') {
155	        const newTool = activeTool === 'texture' ? 'select' : 'texture';
156	        setActiveTool(newTool);
157	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
158	      } else if (key === 'escape') {
159	        setActiveTool('select');
160	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
161	      }
162	    };
163	
164	    window.addEventListener('keydown', handleKeyDown);
165	    return () => {
166	      window.removeEventListener('keydown', handleKeyDown);
167	    };
168	  }, [activeTool]);
169	
170	  // Mesure la largeur naturelle de la barre slicer dès qu'on la voit au repos (mode box,
171	  // aucune transition en cours) — la toute première fois, et à nouveau si jamais elle
172	  // n'a pas encore été capturée (ex : l'app démarre directement sur un autre onglet).
173	  useEffect(() => {
174	    if (boxWidth === null && !isModeling && !isPreviewActive && bottomToolbarRef.current) {
175	      setBoxWidth(bottomToolbarRef.current.getBoundingClientRect().width);
176	    }
177	  }, [boxWidth, isModeling, isPreviewActive]);
178	
179	  useEffect(() => {
180	    if (topToolbarRef.current && buttonRefs.current.size > 0) {
181	      const activeButtonKey = activeTool === 'layers' ? 'layers' : (activeTab === '3d-view' ? 'box' : activeTab);
182	      const activeButton = buttonRefs.current.get(activeButtonKey);
