// Mesure la largeur naturelle de la barre slicer dès qu'on la voit au repos (mode box,
// aucune transition en cours) — la toute première fois, et à nouveau si jamais elle
// n'a pas encore été capturée (ex : l'app démarre directement sur un autre onglet).
useEffect(() => {
  if (boxWidth === null && !isModeling && !isPreviewActive && bottomToolbarRef.current) {
    setBoxWidth(bottomToolbarRef.current.getBoundingClientRect().width);
  }
}, [boxWidth, isModeling, isPreviewActive]);

// Décalage x/y nécessaire pour que la colonne d'outils du mode Prévisualisation vienne se
// coller au bord droit de l'écran, juste sous le ViewCube — recalculé à chaque montage et
// au resize, à partir de la position de repos réelle de `.bottomToolbar` (mesurée hors
// transition, donc sans le `x`/`y` de framer-motion déjà appliqué).
useEffect(() => {
  const recompute = () => {
    const el = bottomToolbarRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    // rect inclut déjà le `x`/`y` courant posé par framer-motion : on les retranche pour
    // retrouver la position de repos (mode box, x=0 y=0) à partir de laquelle calculer le
    // décalage cible.
    const restLeft = rect.left - previewXRef.current;
    const restTop = rect.top - previewYRef.current;
    const restCenterX = restLeft + rect.width / 2;

    const targetCenterX = window.innerWidth - VIEWCUBE_RIGHT - targetGeometry.width / 2;
    const targetTop = VIEWCUBE_BOTTOM + PREVIEW_TOOLBAR_TOP_GAP;

    setPreviewX(targetCenterX - restCenterX);
    setPreviewY(targetTop - restTop);
  };

  recompute();
  window.addEventListener('resize', recompute);
  return () => window.removeEventListener('resize', recompute);
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [boxWidth]);

