45	  const [activeTool, setActiveTool] = useState<'select' | 'move' | 'rotate' | 'scale' | 'texture' | 'layers'>('select');
46	  const [isPreviewActive, setIsPreviewActive] = useState(false);
47	  // Géométrie du conteneur juste avant de lancer la transition en cours : mesurée à la volée
48	  // (voir `playSpaceTransition`) quel que soit le mode de départ (slicer, prévisualisation
