388	          // sans animation. "auto" tant que la largeur naturelle n'a pas encore été mesurée
389	          // (premier rendu), un nombre dès qu'elle l'est — évite un saut visuel une fois
390	          // `boxWidth` connu puisque `targetGeometry.width` vaudra alors la même valeur.
391	          x: targetGeometry.x,
392	          y: targetGeometry.y,
393	          width: isModeling || boxWidth !== null ? targetGeometry.width : "auto",
394	          height: targetGeometry.height,
395	          borderRadius: targetGeometry.borderRadius,
396	          opacity: 1,
