import React, { useState, useRef, useEffect } from 'react';
import { createPortal } from 'react-dom';
import clsx from 'clsx';
import { AnimatePresence, motion } from 'framer-motion';
import {
  Box,
  ChevronRight,
  Circle,
  Eye,
  EyeOff,
  FlipHorizontal2,
  Minus,
  MousePointerSquareDashed,
  PenLine,
  RotateCw,
  Spline,
  Square,
